INSERT INTO `duans` VALUES (1,'Hệ thống quản lý nhân sự HRM','Phát triển hệ thống quản lý nhân sự toàn diện bao gồm: chấm công, tính lương, quản lý nghỉ phép, đánh giá nhân viên và báo cáo nhân sự.','2025-10-01 00:00:00','2025-10-30 00:00:00','dang_chay',2,'2025-10-28 04:56:39','2025-10-28 09:06:29'),(2,'Website bán hàng trực tuyến','Xây dựng website thương mại điện tử với đầy đủ tính năng: quản lý sản phẩm, giỏ hàng, thanh toán online, quản lý đơn hàng và hệ thống CRM.','2024-02-01 00:00:00','2024-08-15 00:00:00','da_hoan_thanh',3,'2025-10-28 04:56:39','2025-10-28 04:56:39'),(3,'Ứng dụng mobile quản lý công việc','Phát triển ứng dụng di động cho việc quản lý công việc cá nhân và nhóm, tích hợp với các công cụ collaboration như Slack, Teams.','2024-09-01 00:00:00','2025-02-28 00:00:00','da_hoan_thanh',2,'2025-10-28 04:56:39','2025-11-06 03:29:34'),(4,'Hệ thống Business Intelligence','Xây dựng hệ thống phân tích dữ liệu kinh doanh với dashboard trực quan, báo cáo tự động và công cụ dự đoán xu hướng.','2024-10-01 00:00:00','2025-04-30 00:00:00','da_hoan_thanh',3,'2025-10-28 04:56:39','2025-11-06 03:29:48'),(5,'Nâng cấp hệ thống bảo mật','Triển khai các biện pháp bảo mật nâng cao: multi-factor authentication, mã hóa dữ liệu, monitoring và logging hệ thống.','2024-11-01 00:00:00','2025-12-21 00:00:00','dang_chay',2,'2025-10-28 04:56:39','2025-11-10 09:31:26'),(6,'Hệ thống ERP tích hợp','Phát triển hệ thống hoạch định tài nguyên doanh nghiệp tích hợp các module: kế toán, kho vận, bán hàng, mua hàng và sản xuất.','2025-01-15 00:00:00','2025-10-31 00:00:00','chua_bat_dau',3,'2025-10-28 04:56:39','2025-10-28 04:56:39'),(7,'Ứng dụng IoT giám sát nhà máy','Xây dựng hệ thống IoT để giám sát các thông số vận hành nhà máy: nhiệt độ, độ ẩm, năng lượng tiêu thụ và cảnh báo sự cố.','2025-02-01 00:00:00','2025-07-31 00:00:00','chua_bat_dau',2,'2025-10-28 04:56:39','2025-10-28 04:56:39'),(8,'Chatbot AI hỗ trợ khách hàng','Phát triển chatbot thông minh sử dụng AI/ML để hỗ trợ khách hàng 24/7, tích hợp với website và các kênh social media.','2025-03-01 00:00:00','2025-06-30 00:00:00','chua_bat_dau',3,'2025-10-28 04:56:39','2025-10-28 04:56:39'),(9,'Nghiên cứu Blockchain trong logistics','Nghiên cứu và triển khai thí điểm công nghệ Blockchain để theo dõi chuỗi cung ứng và đảm bảo tính minh bạch trong logistics.','2025-04-01 00:00:00','2025-12-31 00:00:00','chua_bat_dau',2,'2025-10-28 04:56:39','2025-10-28 04:56:39'),(10,'Platform học tập trực tuyến','Xây dựng nền tảng e-learning với các tính năng: quản lý khóa học, video streaming, quiz tương tác, forum thảo luận và chứng chỉ số.','2025-05-01 00:00:00','2025-11-30 00:00:00','chua_bat_dau',3,'2025-10-28 04:56:39','2025-10-28 04:56:39'),(11,'Hệ thống quản lý tài liệu điện tử','Phát triển hệ thống quản lý tài liệu với tính năng scan, OCR, workflow phê duyệt và lưu trữ cloud. Tạm dừng do thay đổi yêu cầu.','2024-07-01 00:00:00','2025-03-31 00:00:00','chua_bat_dau',2,'2025-10-28 04:56:39','2025-10-28 04:56:39'),(12,'Dự án để test','test dự án','2025-11-10 00:00:00','2025-12-31 00:00:00','chua_bat_dau',2,'2025-11-10 16:10:24','2025-11-10 16:10:24');
/*!40000 ALTER TABLE `duans` ENABLE KEYS */;
UNLOCK TABLES;

